package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.binomialCoefficient.
 * Aiming for maximum branch and line coverage.
 */
public class MathUtils_binomialCoefficient_TriageGen4Test {

    @Test
    public void testBinomialCoefficient_BaseCases() {
        // k = 0 case
        assertEquals(1L, MathUtils.binomialCoefficient(5, 0));
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));

        // n = k case
        assertEquals(1L, MathUtils.binomialCoefficient(5, 5));
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));

        // k = 1 case
        assertEquals(5L, MathUtils.binomialCoefficient(5, 1));

        // k = n - 1 case
        assertEquals(5L, MathUtils.binomialCoefficient(5, 4));
    }

    @Test
    public void testBinomialCoefficient_StandardValues() {
        // (5 choose 2) = 10
        assertEquals(10L, MathUtils.binomialCoefficient(5, 2));
        // (10 choose 3) = 120
        assertEquals(120L, MathUtils.binomialCoefficient(10, 3));
        // (6 choose 3) = 20
        assertEquals(20L, MathUtils.binomialCoefficient(6, 3));
    }

    @Test
    public void testBinomialCoefficient_LargeValues() {
        // Test values that trigger the binomialCoefficientDouble path
        // (60 choose 30) is a large number
        // Using a known value to ensure the double rounding works correctly
        // (30 choose 15) = 155117520
        assertEquals(155117520L, MathUtils.binomialCoefficient(30, 15));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NLessThanK() {
        // n < k should throw IllegalArgumentException
        MathUtils.binomialCoefficient(5, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NNegative() {
        // n < 0 should throw IllegalArgumentException
        MathUtils.binomialCoefficient(-1, 0);
    }

    @Test
    public void testBinomialCoefficient_OverflowCheck() {
        // This test assumes binomialCoefficientDouble returns Double.POSITIVE_INFINITY 
        // or a value that rounds to Long.MAX_VALUE for extremely large n, k
        // to trigger the ArithmeticException. 
        // Given the implementation uses Math.round(binomialCoefficientDouble(n, k))
        // We try to hit a case that results in Long.MAX_VALUE or higher.

        try {
            // Very large n to force overflow
            MathUtils.binomialCoefficient(1000, 500);
        } catch (ArithmeticException e) {
            assertEquals("result too large to represent in a long integer", e.getMessage());
        } catch (Exception e) {
            // If the implementation throws something else, we catch it, 
            // but for coverage we want the ArithmeticException path.
        }
    }

    @Test
    public void testBinomialCoefficient_Symmetry() {
        // (n choose k) == (n choose n-k)
        assertEquals(MathUtils.binomialCoefficient(10, 2), MathUtils.binomialCoefficient(10, 8));
        assertEquals(MathUtils.binomialCoefficient(20, 5), MathUtils.binomialCoefficient(20, 15));
    }
}
